const mathDirection = (mathBaseValue, correctMath, output) => {
  if (mathBaseValue === undefined) return;
  if (mathBaseValue < 1 || mathBaseValue > 9) {
    console.error(`Bad math: ${mathBaseValue}`);
    return;
  }
  const correctValue = correctMath[mathBaseValue];
  if (correctValue === undefined) throw new not_reached/* UnreachableCode */.$();
  return [output.stayOut(), output.standIn1(), output.standIn2(), output.standIn3(), output.standIn4()][correctValue];
};
