      let ifritDir = 'unknown';

      // Flag both sides that ifrit is dashing through as unsafe, while also tracking where he's actually
      // jumped to so we can use it for the infoText
      if (posXVal < 95) {
        data.ifritRadiantPlumeLocations.push('dirW', 'dirE');
        ifritDir = 'dirW';
      } else if (posXVal > 105) {
        data.ifritRadiantPlumeLocations.push('dirW', 'dirE');
        ifritDir = 'dirE';
      } else if (posYVal < 95) {
        data.ifritRadiantPlumeLocations.push('dirN', 'dirS');
        ifritDir = 'dirN';
      } else if (posYVal > 105) {
        data.ifritRadiantPlumeLocations.push('dirN', 'dirS');
        ifritDir = 'dirS';
      }

      // Remove duplicates
      data.ifritRadiantPlumeLocations = data.ifritRadiantPlumeLocations.filter((pos, index) => data.ifritRadiantPlumeLocations.indexOf(pos) === index);
