// For a given criteria func, if there's exactly one person who matches in the stack group
// and exactly one person who matches in the unmarked group, then they can stack together.
// This also filters out weird party comps naturally.
const another_mount_rokkon_couldStackLooseFunc = (stackJob1, stackJob2, unmarkedJob1, unmarkedJob2, func) => {
  const stackCount = another_mount_rokkon_countJob(stackJob1, stackJob2, func);
  const unmarkedCount = another_mount_rokkon_countJob(unmarkedJob1, unmarkedJob2, func);
  return stackCount === 1 && unmarkedCount === 1;
};
const another_mount_rokkon_isMeleeOrTank = x => util/* default.isMeleeDpsJob */.Z.isMeleeDpsJob(x) || util/* default.isTankJob */.Z.isTankJob(x);
const another_mount_rokkon_isSupport = x => util/* default.isHealerJob */.Z.isHealerJob(x) || util/* default.isTankJob */.Z.isTankJob(x);
const another_mount_rokkon_findStackPartners = (data, stack1, stack2, stackOrderOverride) => {
  const party = data.party;
  if (stack1 === undefined || stack2 === undefined) return 'unknown';
  const stacks = [stack1, stack2];
  const unmarked = party.partyNames.filter(x => !stacks.includes(x));
  if (unmarked.length !== 2 || party.partyNames.length !== 4) return 'unknown';
  const [stackJob1, stackJob2] = stacks.map(x => party.jobName(x));
  if (stackJob1 === undefined || stackJob2 === undefined) return 'unknown';
  const [unmarkedJob1, unmarkedJob2] = unmarked.map(x => party.jobName(x));
  if (unmarkedJob1 === undefined || unmarkedJob2 === undefined) return 'unknown';
  const couldStack = func => {
    return another_mount_rokkon_couldStackLooseFunc(stackJob1, stackJob2, unmarkedJob1, unmarkedJob2, func);
  };
  const stackOrder = stackOrderOverride ?? data.triggerSetConfig.stackOrder;
  if (stackOrder === 'meleeRolesPartners' && couldStack(another_mount_rokkon_isMeleeOrTank)) return 'melee';
  if (couldStack(another_mount_rokkon_isSupport)) return 'role';

  // if we get here, then you have a not normal light party comp, e.g. two ranged
  // or you have set the config option to be "rolesPartners" to not prefer melee.
  // For a tank/healer/ranged/ranged comp, this condition below will always be true
  // but make it anyway in case the party comp is something else entirely.
  const stackCount = another_mount_rokkon_countJob(stackJob1, stackJob2, another_mount_rokkon_isSupport);
  const unmarkedCount = another_mount_rokkon_countJob(unmarkedJob1, unmarkedJob2, another_mount_rokkon_isSupport);
  if (stackCount === 2 && unmarkedCount === 0 || stackCount === 0 && unmarkedCount === 2) return 'partner';

  // if something has gone incredibly awry, then just return the default
  return 'unknown';
};
const another_mount_rokkon_stackSpreadResponse = (data, output, collect, stackId, spreadId, hideStackList) => {
  // cactbot-builtin-response
  output.responseOutputStrings = {
    // In a 4 person party with two randomly assigned stacks,
    // there are a couple of different "kinds of pairs" that make sense to call.
    //
    // You can have two melees together and two ranged together,
    // or you can have two supports together and two dps together (role stacks)
    // or you have no melee in your comp, and you could have mixed support and range.
    // Arguably things like "tank+ranged, melee+healer" are possible but are harder to call.
    //
    // Prefer "melee/ranged" stacks here and elsewhere because it keeps
    // the tank and melee together for uptime.
    spreadThenMeleeStack: {
      en: 'Spread => Melees Stack',
      de: 'Verteilen => Nahkämpfer sammeln',
      ja: '散会 => 近接ペア',
      cn: '分散 => 近战分摊',
      ko: '산개 => 근딜 쉐어'
    },
    spreadThenRoleStack: {
      en: 'Spread => Role Stacks',
      de: 'Verteilen => Rollengruppe sammeln',
      ja: '散会 => ロールペア',
      cn: '分散 => 职能分摊',
      ko: '산개 => 역할별 쉐어'
    },
    spreadThenPartnerStack: {
      en: 'Spread => Partner Stacks',
      de: 'Verteilen => Partner sammeln',
      ja: '散会 => ペア',
      cn: '分散 => 和搭档分摊',
      ko: '산개 => 파트너 쉐어'
    },
    meleeStackThenSpread: {
      en: 'Melees Stack => Spread',
      de: 'Nahkämpfer sammeln => Verteilen',
      ja: '近接ペア => 散会',
      cn: '近战分摊 => 分散',
      ko: '근딜 쉐어 => 산개'
    },
    roleStackThenSpread: {
      en: 'Role Stacks => Spread',
      de: 'Rollengruppe sammeln => Verteilen',
      ja: 'ロールペア => 散会',
      cn: '职能分摊 => 分散',
      ko: '역할별 쉐어 => 산개'
    },
    partnerStackThenSpread: {
      en: 'Partner Stacks => Spread',
      de: 'Partner sammeln => Verteilen',
      ja: 'ペア => 散会',
      cn: '和搭档分摊 => 分散',
      ko: '파트너 쉐어 => 산개'
    },
    spreadThenStack: outputs/* default.spreadThenStack */.Z.spreadThenStack,
    stackThenSpread: outputs/* default.stackThenSpread */.Z.stackThenSpread,
    stacks: {
      en: 'Stacks: ${player1}, ${player2}',
      de: 'Sammeln: ${player1}, ${player2}',
      ja: '頭割り: ${player1}, ${player2}',
      cn: '分摊点: ${player1}, ${player2}',
      ko: '쉐어: ${player1}, ${player2}'
    }
  };
  const [stack1, stack2] = collect.filter(x => x.effectId === stackId);
  const spread = collect.find(x => x.effectId === spreadId);
  if (stack1 === undefined || stack2 === undefined || spread === undefined) return;
  const stackTime = parseFloat(stack1.duration);
  const spreadTime = parseFloat(spread.duration);
  const isStackFirst = stackTime < spreadTime;
  const stackType = another_mount_rokkon_findStackPartners(data, stack1.target, stack2.target);
  const stacks = [stack1, stack2].map(x => x.target).sort();
  const [player1, player2] = stacks.map(x => data.party.member(x));
  const stackInfo = hideStackList ? {} : {
    infoText: output.stacks({
      player1: player1,
      player2: player2
    })
  };
  data.stackSpreadFirstMechanic = isStackFirst ? stackType : 'spread';
  data.stackSpreadSecondMechanic = isStackFirst ? 'spread' : stackType;
  if (stackType === 'melee') {
    if (isStackFirst) return {
      alertText: output.meleeStackThenSpread(),
      ...stackInfo
    };
    return {
      alertText: output.spreadThenMeleeStack(),
      ...stackInfo
    };
  } else if (stackType === 'role') {
    if (isStackFirst) return {
      alertText: output.roleStackThenSpread(),
      ...stackInfo
    };
    return {
      alertText: output.spreadThenRoleStack(),
      ...stackInfo
    };
  } else if (stackType === 'partner') {
    if (isStackFirst) return {
      alertText: output.partnerStackThenSpread(),
      ...stackInfo
    };
    return {
      alertText: output.spreadThenPartnerStack(),
      ...stackInfo
    };
  }

  // 'unknown' catch-all
  if (isStackFirst) return {
    alertText: output.stackThenSpread(),
    ...stackInfo
  };
  return {
    alertText: output.spreadThenStack(),
    ...stackInfo
  };
};
const another_mount_rokkon_towerResponse = (data, output) => {
  // cactbot-builtin-response
  output.responseOutputStrings = {
    tetherThenBlueTower: {
      en: 'Tether ${num1} => Blue Tower ${num2}',
      de: 'Verbindung ${num1} => Blauer Turm ${num2}',
      ja: '線${num1} => 青塔${num2}',
      cn: '连线 ${num1} => 蓝塔 ${num2}',
      ko: '선 ${num1} => 파랑 기둥 ${num2}'
    },
    tetherThenOrangeTower: {
      en: 'Tether ${num1} => Orange Tower ${num2}',
      de: 'Verbindung ${num1} => Orangener Turm ${num2}',
      ja: '線${num1} => 赤塔${num2}',
      cn: '连线 ${num1} => 橙塔 ${num2}',
      ko: '선 ${num1} => 주황 기둥 ${num2}'
    },
    tether: {
      en: 'Tether ${num}',
      de: 'Verbindung ${num}',
      ja: '線${num}',
      cn: '连线 ${num}',
      ko: '선 ${num}'
    },
    blueTower: {
      en: 'Blue Tower ${num}',
      de: 'Blauer Turm ${num}',
      ja: '青塔${num}',
      cn: '蓝塔 ${num}',
      ko: '파랑 기둥 ${num}'
    },
    orangeTower: {
      en: 'Orange Tower ${num}',
      de: 'Orangener Turm ${num}',
      ja: '赤塔${num}',
      cn: '橙塔 ${num}',
      ko: '주황 기둥 ${num}'
    },
    num1: outputs/* default.num1 */.Z.num1,
    num2: outputs/* default.num2 */.Z.num2,
    num3: outputs/* default.num3 */.Z.num3,
    num4: outputs/* default.num4 */.Z.num4
  };

  // data.rousingTowerCount is 0-indexed
  // towerNum for display is 1-indexed
  const theseTowers = data.rousingCollect[data.rousingTowerCount];
  const towerNum = data.rousingTowerCount + 1;
  data.rousingTowerCount++;
  if (theseTowers === undefined) return;
  const numMap = {
    1: output.num1(),
    2: output.num2(),
    3: output.num3(),
    4: output.num4()
  };
  const numStr = numMap[towerNum];
  if (numStr === undefined) return;
  if (data.me === theseTowers.blue) return {
    alertText: output.blueTower({
      num: numStr
    })
  };
  if (data.me === theseTowers.orange) return {
    alertText: output.orangeTower({
      num: numStr
    })
  };
  const nextTowers = data.rousingCollect[towerNum + 1];
  const nextNumStr = numMap[towerNum + 1];
  if (towerNum === 4 || nextTowers === undefined || nextNumStr === undefined) return {
    infoText: output.tether({
      num: numStr
    })
  };
  if (data.me === nextTowers.blue) return {
    infoText: output.tetherThenBlueTower({
      num1: numStr,
      num2: nextNumStr
    })
  };
  if (data.me === nextTowers.orange) return {
    infoText: output.tetherThenOrangeTower({
      num1: numStr,
      num2: nextNumStr
    })
  };

  // Just in case...
  return {
    infoText: output.tether({
      num: numStr
    })
  };
};
