      if (data.party.isDPS(myBuddy)) myBuddyRole = output.dps();else if (data.party.isTank(myBuddy)) myBuddyRole = output.tank();else if (data.party.isHealer(myBuddy)) myBuddyRole = output.healer();else myBuddyRole = output.unknown();
