const towerColors = (/* unused pure expression or super */ null && (['green', 'blue', 'purple']));
const perfectedConcepts = ['alpha', 'beta', 'gamma'];
const p8s_centerX = 100;
const p8s_centerY = 100;
const positionMatchesTo8Dir = combatant => {
  const x = parseFloat(combatant.x) - p8s_centerX;
  const y = parseFloat(combatant.y) - p8s_centerY;

  // Dirs: N = 0, NE = 1, ..., NW = 7
  return Math.round(4 - 4 * Math.atan2(x, y) / Math.PI) % 8;
};
const p8s_positionTo8Dir = combatant => {
  const x = combatant.PosX - p8s_centerX;
  const y = combatant.PosY - p8s_centerY;

  // Dirs: N = 0, NE = 1, ..., NW = 7
  return Math.round(4 - 4 * Math.atan2(x, y) / Math.PI) % 8;
};
const headingTo8Dir = heading => {
  // Dirs: N = 0, NE = 1, ..., NW = 7
  return (2 - Math.round(heading * 8 / Math.PI) / 2 + 2) % 8;
};
