  id: 'MountOrdeals',
  zoneId: zone_id/* default.MountOrdeals */.Z.MountOrdeals,
  timelineFile: 'rubicante.txt',
  initData: () => {
    return {
      purgation: 1,
      dualfireTarget: false
    };
  },
